package com.example

import com.example.ExamQuestionHelper.QSpec

internal object CivicsLiveExamGovernanceBank1 {
  private const val T = "යහපාලනය, නීතියේ ආධිපත්‍යය, RTI හා ගැටුම් නිරාකරණය"

  private fun q(
    stem: String,
    c: String,
    d1: String,
    d2: String,
    d3: String,
    exp: String
  ) = QSpec(T, stem, c, listOf(d1, d2, d3), exp)

  fun questions(): List<QSpec> = listOf(
    q("රාජ්‍ය පාලන ආයතන මහජන අවශ්‍යතා වෙනුවෙන් පාරදෘශ්‍යව, වගකීමෙන් හා සාධාරණව මෙහෙයවීමේ ක්‍රියාවලිය කුමක්ද?", "යහපාලනය (Good Governance)", "මධ්‍යගත පාලනය", "ඒකාධිපති පාලනය", "රදළ පාලනය", "පොදු සම්පත් දූෂණයෙන් තොරව ජනතා සහභාගීත්වයෙන් හා නීතිගරුකව කළමනාකරණය කිරීම යහපාලනයයි."),
    q("එක්සත් ජාතීන්ගේ සංවර්ධන වැඩසටහන (UNDP / UNESCAP) හඳුන්වා දී ඇති යහපාලනයේ මූලික ලක්ෂණ ගණන කීයද?", "8", "3", "5", "12", "සහභාගීත්වය, නීතියේ ආධිපත්‍යය, විනිවිදභාවය, ප්‍රතිචාරාත්මක බව, සම්මුතිය, සාධාරණත්වය, කාර්යක්ෂමතාව සහ වගවීම යන 8යි."),
    q("තීරණ ගන්නා නිලධාරීන් හා මහජන නියෝජිතයන් තම ක්‍රියා පිළිබඳව ජනතාවට හා අදාළ ආයතනවලට පිළිතුරු බැඳීමේ ගුණාංගය කුමක්ද?", "වගවීම (Accountability)", "රහස්‍යභාවය", "ඒකාබද්ධතාව", "ස්වෛරීභාවය", "රජයේ මුදල් හා බලය භාවිත කිරීමේදී පාලකයන් මහජනතාවට වගකිව යුතු වීම වගවීමයි."),
    q("රාජ්‍ය ආයතන ගන්නා තීරණ, ටෙන්ඩර් ක්‍රියාවලි හා මූල්‍ය වියදම් නීත්‍යානුකූලව මහජනතාවට විවෘතව පැවතීම කුමන ලක්ෂණයද?", "විනිවිදභාවය (Transparency)", "සම්මුතිගත බව", "අධිකාරිත්වය", "ප්‍රභූවාදය", "තොරතුරු සැඟවීම වෙනුවට ජනතාවට පරීක්ෂා කළ හැකි විවෘත පාලනය විනිවිදභාවය වේ."),
    q("ජනතාවගේ පැමිණිලි හා අවශ්‍යතා කෙරෙහි අනවශ්‍ය ප්‍රමාදයකින් තොරව නිශ්චිත කාලසීමාවක් තුළ කඩිනමින් ක්‍රියාත්මක වීම කුමක්ද?", "ප්‍රතිචාරාත්මක බව (Responsiveness)", "අනුපාතික බව", "විමධ්‍යගත බව", "බහුත්වවාදය", "රාජ්‍ය ආයතන පුරවැසි ඉල්ලීම්වලට සාධාරණ කාලයක් ඇතුළත සේවා සැලසීම ප්‍රතිචාරාත්මක බවයි."),
    q("සීමිත මහජන සම්පත් හා කාලය නාස්ති නොකර අඩුම වියදමින් උපරිම ගුණාත්මක ප්‍රතිඵල ජනතාවට ලබාදීම කුමන ලක්ෂණයද?", "ඵලදායීතාව හා කාර්යක්ෂමතාව", "නීතිමය මුක්තිය", "සංවෘත පාලනය", "බහුවිධ ඡන්ද බලය", "සම්පත් මනා ලෙස කළමනාකරණය කර ජනතා අපේක්ෂා සපුරාලීම යහපාලනයේ කාර්යක්ෂමතාවයි."),
    q("බහුවිධ සමාජයක සියලු ජන කොටස්වලට සාධාරණව සලකමින් පොදු එකඟතාවක් මත තීරණ ගැනීම කුමන යහපාලන ලක්ෂණද?", "සම්මුතිගත බව හා අන්තර්කරණය", "ඒකපාක්ෂික තීරණ ගැනීම", "බලහත්කාරී පාලනය", "සීමිත නියෝජනය", "විවිධ කණ්ඩායම්වල අදහස්වලට ඇහුම්කන් දී කිසිවෙකු කොන් නොකර තීරණ ගැනීම මෙයින් අදහස් වේ."),
    q("රටේ ඉහළම පාලකයාගේ සිට සාමාන්‍ය පුරවැසියා දක්වා සෑම දෙනාම නීතියට යටත් බව ප්‍රකාශ කරන සංකල්පය කුමක්ද?", "නීතියේ ආධිපත්‍යය (Rule of Law)", "රාජ්‍ය මුක්තිය", "අත්තනෝමතික පාලනය", "ප්‍රභූ වරප්‍රසාදය", "කිසිවෙකු නීතියට ඉහළින් නොසිටීම සහ සියල්ලන්ට සමාන නීතිය ක්‍රියාත්මක වීම නීතියේ ආධිපත්‍යයයි."),
    q("'නීතියේ ආධිපත්‍යය' (Rule of Law) පිළිබඳ ප්‍රකට මූලධර්ම තුන ඉදිරිපත් කළ බ්‍රිතාන්‍ය නීති විශාරදයා කවුද?", "ඒ.වී. ඩයිසි (A.V. Dicey)", "ජෝන් ඔස්ටින්", "හෙන්රි ඩුනන්ට්", "ඇඩම් ස්මිත්", "බ්‍රිතාන්‍ය විද්වත් A.V. Dicey නීතියේ උත්තරීතරභාවය, සමානාත්මතාව හා අධිකරණ රැකවරණය විස්තර කළේය."),
    q("ඒ.වී. ඩයිසිගේ නිර්වචනයට අනුව 'අත්තනෝමතික බලය නොතිබී සාමාන්‍ය නීතියේ උත්තරීතරභාවය' යන්නෙන් අදහස් වන්නේ කුමක්ද?", "පැහැදිලිව නීති කඩ කිරීමකදී හැර අධිකරණ ක්‍රියාමාර්ගයකින් තොරව කිසිවෙකුට දඬුවම් නොකිරීම", "පාලකයන්ට හිතූ පරිදි සිරගත කිරීමට හැකි වීම", "ධනවතුන්ට විශේෂ උසාවි පැවතීම", "නීති සැමවිටම රහසිගතව තැබීම", "විධිමත් නීතිය හා අධිකරණ තීන්දුවක් මත මිස රාජ්‍ය නිලධාරීන්ගේ කැමැත්තට දඬුවම් දිය නොහැක."),
    q("ශ්‍රී ලංකාවේ තොරතුරු දැනගැනීමේ අයිතිවාසිකම පිළිබඳ පනත (RTI Act) සම්මත කරන ලද්දේ කුමන වර්ෂයේදීද?", "2016 (2016 අංක 12 දරන පනත)", "1996 (1996 අංක 21 දරන පනත)", "2005 (2005 අංක 34 දරන පනත)", "1988 (1988 අංක 72 දරන පනත)", "19 වන සංශෝධනයේ 14අ වගන්තිය බලාත්මක කිරීමට 2016 අංක 12 දරන RTI පනත සම්මත කෙරිණි."),
    q("2016 අංක 12 දරන තොරතුරු දැනගැනීමේ පනත යටතේ සෑම පොදු අධිකාරියකම පත් කළ යුතු නිලධාරියා කවුද?", "තොරතුරු නිලධාරී (Information Officer)", "විගණකාධිපති", "දිසා විනිසුරු", "මැතිවරණ කොමසාරිස්", "පුරවැසියන්ගේ තොරතුරු ඉල්ලීම් භාරගෙන නියමිත කාලයට පිළිතුරු සැපයීමට තොරතුරු නිලධාරියෙකු පත් කළ යුතුය."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ සාමාන්‍ය තොරතුරු ඉල්ලීමක් සඳහා තොරතුරු නිලධාරියා තීරණය දැනුම් දිය යුතු කාලය කුමක්ද?", "වැඩ කරන දින 14ක් ඇතුළත", "මාස 6ක් ඇතුළත", "වසර 1ක් ඇතුළත", "දින 90ක් ඇතුළත", "තොරතුරු ලබාදීම හෝ ප්‍රතික්ෂේප කිරීම පිළිබඳව හැකි ඉක්මනින් හෝ වැඩ කරන දින 14ක් ඇතුළත දැනුම් දිය යුතුය."),
    q("පුද්ගලයෙකුගේ ජීවිතයට හෝ පෞද්ගලික නිදහසට අදාළ හදිසි තොරතුරක් ඉල්ලා සිටි විට පිළිතුරු දිය යුතු උපරිම කාලය කුමක්ද?", "පැය 48ක් ඇතුළත", "සති 4ක් ඇතුළත", "මාස 3ක් ඇතුළත", "දින 21ක් ඇතුළත", "ජීවිතයට හා පුද්ගල නිදහසට තර්ජනයක් ඇති කරුණුවලදී පැය 48ක් ඇතුළත තොරතුරු ලබාදීම නීතිමය වගකීමකි."),
    q("තොරතුරු නිලධාරියෙකු තොරතුරු දීම ප්‍රතික්ෂේප කළහොත් පුරවැසියෙකුට පළමුවෙන්ම අභියාචනා කළ හැක්කේ කා වෙතද?", "අදාළ ආයතනයේ 'නම් කළ නිලධාරියා' (Designated Officer) වෙත", "ජනාධිපති ලේකම් වෙත", "පොලිස් ස්ථානාධිපති වෙත", "ශ්‍රේෂ්ඨාධිකරණයට සෘජුවම", "ප්‍රතික්ෂේප කිරීමෙන් දින 14ක් ඇතුළත ආයතනයේ නම් කළ නිලධාරියාට අභියාචනා කළ යුතුය."),
    q("නම් කළ නිලධාරියාගේ තීරණයෙන්ද සෑහීමකට පත් නොවන පුරවැසියෙකුට මාස දෙකක් ඇතුළත අභියාචනා කළ හැකි ස්වාධීන ආයතනය කුමක්ද?", "තොරතුරු දැනගැනීමේ අයිතිවාසිකම පිළිබඳ කොමිෂන් සභාව", "රාජ්‍ය සේවා කොමිෂන් සභාව", "මුදල් කොමිෂන් සභාව", "මැතිවරණ කොමිෂන් සභාව", "නම් කළ නිලධාරියාගෙන් සහනයක් නොලැබුණහොත් ස්වාධීන RTI කොමිෂන් සභාවට අභියාචනා කළ හැක."),
    q("තොරතුරු දැනගැනීමේ පනතේ 5 වන වගන්තිය යටතේ තොරතුරු ලබාදීම ප්‍රතික්ෂේප කළ හැකි නීත්‍යානුකූල අවස්ථාවක් කුමක්ද?", "ජාතික ආරක්ෂාවට හෝ රාජ්‍යයේ ආරක්ෂාවට බරපතළ හානියක් වන තොරතුරු", "රජයේ පාසල් අධ්‍යාපන වියදම්", "නගර සභාවේ කසළ ටෙන්ඩර් ගාස්තු", "මාර්ග සංවර්ධන ව්‍යාපෘති ඇස්තමේන්තු", "ජාතික ආරක්ෂාව, පෞද්ගලිකත්වය, කැබිනට් තීරණ නොගත් සංදේශ හා විභාග රහස් වැනි ව්‍යතිරේක 5 වන වගන්තියේ ඇත."),
    q("තොරතුරු ලබාදීමේ ව්‍යතිරේකයක් පැවතුණද මහජනතාවගේ පොදු යහපත ඊට වඩා බලවත් නම් තොරතුරු හෙළි කළ යුතු බව දක්වන මූලධර්මය කුමක්ද?", "මහජන සුබසිද්ධිය ප්‍රමුඛ වීම (Public Interest Override)", "පරිපාලන රහස්‍යභාවය", "රාජ්‍ය මුක්තිය", "නිෂේධ බලය", "5(4) වගන්තිය අනුව තොරතුර හෙළි කිරීමෙන් ඇතිවන මහජන යහපත හානියට වඩා වැඩි නම් එය ලබාදිය යුතුය."),
    q("RTI පනත යටතේ පුරවැසියෙකු තොරතුරු ඉල්ලුම්පත්‍රයක් භාරදෙන විට තොරතුර අවශ්‍ය වීමට හේතුව සඳහන් කිරීම අනිවාර්යද?", "නැත, හේතුවක් දැක්වීම අවශ්‍ය නොවේ", "ඔව්, උසාවි අවසරයක් අවශ්‍ය වේ", "ඔව්, ග්‍රාම නිලධාරී සහතිකයක් අවශ්‍ය වේ", "ඔව්, පොලිස් වාර්තාවක් අවශ්‍ය වේ", "පුරවැසියෙකුට රජයේ තොරතුරක් ඉල්ලීමේදී තමන්ට එම තොරතුර අවශ්‍ය කුමකටදැයි හේතු දැක්වීම අනිවාර්ය නොවේ."),
    q("රාජ්‍ය ආයතන විසින් ජනතාව ඉල්ලීමට පෙරම තම වෙබ් අඩවි හා පුවරු මඟින් වාර්ෂික වාර්තා හා වියදම් ප්‍රසිද්ධ කිරීම කුමක්ද?", "පූර්ව හෙළිදරව් කිරීම (Proactive Disclosure)", "රහසිගත විගණනය", "අධිකරණ සමාලෝචනය", "සංවෘත කාරක සභා ක්‍රමය", "RTI පනතේ 8 හා 9 වගන්ති අනුව අමාත්‍යාංශ හා ආයතන මූලික තොරතුරු ස්වේච්ඡාවෙන් ප්‍රකාශ කළ යුතුය."),
    q("ශ්‍රී ලංකාවේ අල්ලස් හා දූෂණ විමර්ශනය කිරීම සඳහා 2023 අංක 9 දරන දූෂණ විරෝධී පනත යටතේ ශක්තිමත් කළ ස්වාධීන ආයතනය කුමක්ද?", "අල්ලස් හෝ දූෂණ චෝදනා විමර්ශන කොමිෂන් සභාව (CIABOC)", "මැතිවරණ කොමිෂන් සභාව", "රාජ්‍ය භාෂා කොමිෂන් සභාව", "විශ්වවිද්‍යාල ප්‍රතිපාදන කොමිසම", "රාජ්‍ය හා පෞද්ගලික අංශයේ දූෂණ වැළැක්වීම හා වත්කම් ප්‍රකාශ අධීක්ෂණය CIABOC මඟින් කෙරේ."),
    q("මැති ඇමතිවරුන් සහ උසස් රාජ්‍ය නිලධාරීන් වාර්ෂිකව තම ආදායම් හා දේපළ විස්තර ඉදිරිපත් කිරීමේ ක්‍රමය කුමක්ද?", "වත්කම් හා බැරකම් ප්‍රකාශ ඉදිරිපත් කිරීම", "මැතිවරණ ප්‍රතිපත්ති ප්‍රකාශනය", "හැන්සාඩ් වාර්තාව", "වරිපනම් ලේඛනය", "අයථා ධන ඉපැයීම් හා දූෂණ වැළැක්වීම සඳහා නිලධාරීන්ගේ වත්කම් බැරකම් ප්‍රකාශ අනිවාර්ය කර ඇත."),
    q("රාජ්‍ය ආයතනවල මූල්‍ය හා පරිපාලන අක්‍රමිකතා පිළිබඳව අභ්‍යන්තර සේවකයන් නීතිගරුකව හෙළිදරව් කිරීමේ ක්‍රියාවලිය කුමක්ද?", "විස්ල්බ්ලෝවින් හෙවත් අක්‍රමිකතා හෙළිදරව් කිරීම (Whistleblowing)", "ජෙරිමැන්ඩරින්", "පක්ෂ මාරු කිරීම", "නිහඬ කාලසීමාව", "සත්භාවයෙන් දූෂණ හෙළි කරන පුද්ගලයන් හා තොරතුරු නිලධාරීන් ආරක්ෂා කිරීම RTI හා දූෂණ විරෝධී නීතිවල අරමුණකි."),
    q("ශ්‍රී ලංකාවේ ස්වාධීන කොමිෂන් සභා සඳහා සුදුසු සාමාජිකයන් නිර්දේශ කරන ඉහළම ව්‍යවස්ථාපිත මණ්ඩලය කුමක්ද?", "ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාව (Constitutional Council)", "කැබිනට් අනුකාරක සභාව", "පළාත් සභා සභාපති සංසදය", "සමථ මණ්ඩල කොමිසම", "21 වන සංශෝධනය යටතේ කථානායක ප්‍රමුඛ 10 දෙනෙකුගෙන් යුත් ව්‍යවස්ථා සභාව ස්වාධීන පත්වීම් අනුමත කරයි."),
    q("21 වන ව්‍යවස්ථා සංශෝධනය අනුව ආණ්ඩුක්‍රම ව්‍යවස්ථා සභාවේ සභාපතිත්වය දරන්නේ කවුද?", "පාර්ලිමේන්තු කථානායකවරයා", "විධායක ජනාධිපතිවරයා", "අගවිනිසුරුවරයා", "විපක්ෂ නායකවරයා", "ව්‍යවස්ථා සභාවේ සාමාජිකයන් 10 දෙනා අතරින් නිල බලයෙන් සභාපති වන්නේ කථානායකවරයාය."),
    q("පොලිස් නිලධාරීන් විසින් සිදු කරන බලය අයුතු ලෙස භාවිත කිරීම හා මහජන පැමිණිලි විභාග කරන ස්වාධීන ආයතනය කුමක්ද?", "ජාතික පොලිස් කොමිෂන් සභාව (NPC)", "රාජ්‍ය සේවා කොමිෂන් සභාව", "මුදල් කොමිෂන් සභාව", "තොරතුරු කොමිෂන් සභාව", "පොලිස් සේවයේ ස්වාධීනත්වය රැකීම හා මහජන පැමිණිලි විමර්ශනය ජාතික පොලිස් කොමිසමේ කාර්යයකි."),
    q("රාජ්‍ය සේවයේ නිලධාරීන්ගේ පත්වීම්, උසස්වීම්, ස්ථාන මාරු හා විනය පාලනය දේශපාලන බලපෑම්වලින් තොරව ඉටු කරන ආයතනය කුමක්ද?", "රාජ්‍ය සේවා කොමිෂන් සභාව (PSC)", "ප්‍රසම්පාදන කොමිසම", "සීමා නිර්ණ කොමිසම", "මැතිවරණ කොමිසම", "රාජ්‍ය නිලධාරීන්ට අසාධාරණයක් වූ විට පරිපාලන අභියාචනා විනිශ්චය සභාවටද ඉදිරිපත් විය හැක."),
    q("රජයේ භාණ්ඩ හා සේවා මිලදී ගැනීම් සහ ටෙන්ඩර් ක්‍රියාවලි විනිවිදභාවයෙන් සිදු කිරීමට ප්‍රමිතීන් නියම කරන ආයතනය කුමක්ද?", "ජාතික ප්‍රසම්පාදන කොමිෂන් සභාව (National Procurement Commission)", "අධිකරණ සේවා කොමිෂන් සභාව", "මානව හිමිකම් කොමිසම", "රාජ්‍ය භාෂා කොමිසම", "රාජ්‍ය මුදල් නාස්තිය හා ටෙන්ඩර් දූෂණ වැළැක්වීම සඳහා ප්‍රසම්පාදන මාර්ගෝපදේශ නිකුත් කෙරේ."),
    q("රාජ්‍ය පරිපාලන නිලධාරීන්ගේ අකාර්යක්ෂමතාව හෝ අසාධාරණ තීරණ නිසා පුරවැසියන්ට සිදුවන පීඩා විමර්ශනය කරන නිලධාරියා කවුද?", "ඔම්බුඩ්ස්මන්වරයා (පරිපාලන කටයුතු පිළිබඳ පාර්ලිමේන්තු කොමසාරිස්)", "රේගු අධ්‍යක්ෂ ජනරාල්", "විදේශ ලේකම්", "මහ බැංකු අධිපති", "1809 දී ස්වීඩනයෙන් ඇරඹි ඔම්බුඩ්ස්මන් ක්‍රමය ශ්‍රී ලංකාවේ 1981 දී ස්ථාපිත කෙරිණි."),
    q("ඔම්බුඩ්ස්මන්වරයා වෙත පුරවැසියෙකු පැමිණිල්ලක් ඉදිරිපත් කිරීමේදී මූලිකවම අවධානය යොමු කෙරෙන්නේ කුමන කාරණය කෙරෙහිද?", "රාජ්‍ය ආයතනවල 'පරිපාලන අසාධාරණ හා වැරදි පාලනය' (Maladministration)", "පවුලේ ඉඩම් බෙදාගැනීමේ ආරවුල්", "විදේශීය ක්‍රිකට් තරග නීති", "පෞද්ගලික බැංකු පොලී අනුපාත", "රජයේ දෙපාර්තමේන්තු, සංස්ථා හා පළාත් පාලන ආයතනවල පරිපාලන අසාධාරණ ඔම්බුඩ්ස්මන් විමර්ශනය කරයි."),
    q("රාජ්‍ය ආයතනයකින් මහජනතාවට ලබාදෙන සේවාවන්, අවශ්‍ය ලියකියවිලි හා ගතවන කාලය ප්‍රසිද්ධියේ ප්‍රදර්ශනය කරන ලේඛනය කුමක්ද?", "පුරවැසි ප්‍රඥප්තිය (Citizen's Charter)", "හැන්සාඩ් වාර්තාව", "මැතිවරණ ප්‍රකාශනය", "ජාතික අයවැය කෙටුම්පත", "පුරවැසි ප්‍රඥප්තිය නිසා සේවා ලාභියාට ප්‍රමාදයකින් තොරව තම කාර්යය ඉටු කර ගැනීමට හැකියාව ලැබේ."),
    q("රාජ්‍ය සේවා කටයුතු පරිගණක හා අන්තර්ජාල තාක්ෂණය ඔස්සේ කඩිනමින් හා පෝලිම්වලින් තොරව ලබාදීමේ ක්‍රමය කුමක්ද?", "විද්‍යුත් පාලනය (e-Governance)", "සාම්ප්‍රදායික ලිපිගොනු ක්‍රමය", "වක්‍ර බදු ක්‍රමය", "සංවෘත පරිපාලනය", "මාර්ගගත පද්ධති (Online) මඟින් විනිවිදභාවය වැඩි වී අල්ලස් හා ප්‍රමාදයන් අවම වේ."),
    q("ශ්‍රී ලංකාවේ 2018 අංක 19 දරන ජාතික විගණන පනත සම්මත කිරීමේ ප්‍රධානතම අරමුණ කුමක්ද?", "රාජ්‍ය මූල්‍ය විනය ශක්තිමත් කර අලාභ හානි සිදුකරන නිලධාරීන්ගෙන් අධිභාර අයකර ගැනීම", "පළාත් සභා සංඛ්‍යාව වැඩි කිරීම", "මැතිවරණ වියදම් ඉවත් කිරීම", "පෞද්ගලික බැංකු වැසීම", "විගණකාධිපතිට අධිභාර නියම කිරීමේ බලය හා ජාතික විගණන කාර්යාලය ස්වාධීන කිරීම මෙයින් සිදුවිය."),
    q("පාර්ලිමේන්තුවේ 'පොදු ව්‍යාපාර පිළිබඳ කාරක සභාව' (COPE) විසින් විමර්ශනය කරනු ලබන්නේ කුමන ආයතනවල මූල්‍ය කටයුතුද?", "රාජ්‍ය සංස්ථා, ව්‍යවස්ථාපිත මණ්ඩල හා රජය සතු ව්‍යාපාරවල", "පෞද්ගලික සිල්ලර වෙළඳසැල්වල", "විදේශීය තානාපති කාර්යාලවල", "පෞද්ගලික පාසල්වල", "ලංකා විදුලිබල මණ්ඩලය, ජල සම්පාදන මණ්ඩලය වැනි රාජ්‍ය ව්‍යවසායන්ගේ ගිණුම් COPE කමිටුව පරීක්ෂා කරයි."),
    q("රජයේ අමාත්‍යාංශ, දෙපාර්තමේන්තු සහ දිස්ත්‍රික් ලේකම් කාර්යාලවල වියදම් පාර්ලිමේන්තුව හමුවේ පරීක්ෂා කරන කමිටුව කුමක්ද?", "රජයේ ගිණුම් පිළිබඳ කාරක සභාව (COPA)", "සමථ මණ්ඩල සංගමය", "ජාතික ප්‍රසම්පාදන කමිටුව", "අධිකරණ සේවා කමිටුව", "විගණකාධිපති වාර්තා පදනම් කරගෙන රාජ්‍ය දෙපාර්තමේන්තුවල මූල්‍ය විනය COPA කමිටුවෙන් පරීක්ෂා කෙරේ."),
    q("යහපාලනය තුළ 'සමානාත්මතාව හා අපක්ෂපාතීත්වය' බිඳ වැටීමට ප්‍රධාන වශයෙන් බලපාන දූෂිත ක්‍රියාවක් කුමක්ද?", "ඥාති සංග්‍රහය හා දේශපාලන පක්ෂපාතීත්වය (Nepotism & Favoritism)", "විවෘත ටෙන්ඩර් කැඳවීම", "පුරවැසි ප්‍රඥප්තිය ප්‍රදර්ශනය කිරීම", "වත්කම් ප්‍රකාශ ලබාගැනීම", "සුදුසුකම් නොසලකා හිතවතුන්ට හා ඥාතීන්ට තනතුරු හා කොන්ත්‍රාත් දීම යහපාලනයට පටහැනිය."),
    q("රජයේ කාර්යාලයකින් ලිපියක් හෝ බලපත්‍රයක් ඉක්මනින් කරගැනීම සඳහා නිලධාරියෙකුට නීතිවිරෝධීව මුදල් හෝ තෑගි දීම කුමන වරදක්ද?", "අල්ලස් ගැනීම හා දීම (Bribery)", "සේවා ප්‍රවර්ධනය", "විධායක වරප්‍රසාදය", "සමථකරණය", "නියමිත රාජකාරියක් ඉටු කිරීමට හෝ නොකිරීමට අයුතු ලෙස මුදල් ලබාගැනීම නීතියෙන් දඬුවම් ලැබිය හැකි වරදකි."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ රාජ්‍ය ආයතනවලට අමතරව වෙනත් කුමන ආයතනවලින් තොරතුරු ලබාගැනීමට පුරවැසියන්ට අයිතිය ඇත්ද?", "රජයේ අරමුදල් හෝ කොන්ත්‍රාත් ලබන පෞද්ගලික හා රාජ්‍ය නොවන ආයතනවලින් (පොදු අරමුදල්වලට අදාළව)", "ඕනෑම පවුලක පෞද්ගලික දිනපොත්වලින්", "පෞද්ගලික වෛද්‍ය සායනවල රෝගී වාර්තාවලින්", "බැංකු ගනුදෙනුකරුවන්ගේ රහස් ගිණුම්වලින්", "මහජන මුදල් වැය වන හෝ පොදු සේවාවක් සපයන ආයතන RTI පනතේ 'පොදු අධිකාරි' අර්ථකථනයට අයත් වේ."),
    q("පුද්ගලයෙකුගේ 'නීතිය ඉදිරියේ ආරක්ෂාව' සහතික කිරීමට යුක්තිය පසිඳලීමේදී පැවතිය යුතු මූලික ලක්ෂණය කුමක්ද?", "අධිකරණයේ ස්වාධීනත්වය හා අපක්ෂපාතීත්වය", "පාලක පක්ෂයේ අනුමැතිය", "රහසිගත දඬුවම් ක්‍රම", "ධනය මත තීරණ වෙනස් වීම", "ස්වාධීන හා බියෙන් තොර අධිකරණයක් නොමැතිව නීතියේ ආධිපත්‍යය රැකගත නොහැක."),
    q("යහපාලනය ශක්තිමත් කිරීම සඳහා පුරවැසියන්ට දැක්විය හැකි සක්‍රීය දායකත්වයක් වන්නේ කුමක්ද?", "සමාජ විගණනයට එක්වීම, අල්ලස් ප්‍රතික්ෂේප කිරීම හා RTI මඟින් ප්‍රශ්න කිරීම", "රජයේ සියලු බදු පැහැර හැරීම", "ඡන්දය දීමෙන් වැළකී සිටීම", "අසත්‍ය කටකතා පැතිරවීම", "විමසිලිමත් හා සක්‍රීය පුරවැසි සමාජයක් නොමැතිව රාජ්‍ය ආයතනවල වගවීම රැකිය නොහැක."),
    q("ප්‍රාදේශීය හෝ ජාතික මට්ටමින් ගැටුමක් ඇති වීමට පෙර එහි මූලික ලක්ෂණ හඳුනාගෙන සාමකාමීව වළක්වා ගැනීමේ ක්‍රියාවලිය කුමක්ද?", "ගැටුම් වැළැක්වීම (Conflict Prevention)", "ආයුධ සන්නද්ධ මැදිහත්වීම", "පළිගැනීමේ චක්‍රය", "ආර්ථික සම්බාධක පැනවීම", "අසාධාරණ හා සන්නිවේදන බිඳවැටීම් කලින් හඳුනාගෙන විසඳීමෙන් ප්‍රචණ්ඩ ගැටුම් වළක්වා ගත හැක."),
    q("පුද්ගලයන් දෙදෙනෙකු හෝ කණ්ඩායම් දෙකක් අතර පවතින ආරවුලක් තෙවන පාර්ශ්වයක මැදිහත්වීමකින් තොරව දෙපාර්ශ්වයම සාකච්ඡා කර විසඳාගැනීම කුමක්ද?", "සාකච්ඡාව / සම්මුතිකරණය (Negotiation)", "නඩු පැවරීම (Litigation)", "බේරුම්කරණය (Arbitration)", "පොලිස් අත්අඩංගුවට ගැනීම", "සම්බන්ධ පාර්ශ්ව දෙක පමණක් සෘජුවම සංවාදයෙන් එකඟතාවයකට එළඹීම Negotiation වේ."),
    q("ආරවුලකදී මධ්‍යස්ථ තෙවන පාර්ශ්වයක් සහාය වී දෙපාර්ශ්වයේම කැමැත්තෙන් ස්වේච්ඡා විසඳුමකට පැමිණීමේ ක්‍රමය කුමක්ද?", "සමථකරණය (Mediation)", "අධිකරණ නඩු විභාගය", "ඒකපාර්ශ්වික නියෝගය", "බේරුම්කරණ තීන්දුව", "සමථකරු තීන්දු බලෙන් නොපනවන අතර පාර්ශ්ව දෙකටම පිළිගත හැකි විසඳුමක් සොයා ගැනීමට මග පෙන්වයි."),
    q("ශ්‍රී ලංකාවේ ප්‍රජා මට්ටමින් සුළු සිවිල් හා පවුල් ආරවුල් සාමකාමීව විසඳීමට ස්ථාපිත කළ ආයතනය කුමක්ද?", "සමථ මණ්ඩල (Mediation Boards)", "මහාධිකරණ", "රේගු විනිශ්චය සභා", "වාණිජ බැංකු", "1988 අංක 72 දරන සමථ මණ්ඩල පනත යටතේ ගැටුම් සුහදව විසඳීමට සමථ මණ්ඩල පිහිටුවා ඇත."),
    q("සමථ මණ්ඩල පනත අනුව ග්‍රාමීය සුළු ආරවුලක් (රුපියල් ලක්ෂ 10ට අඩු) අධිකරණයට ගෙන යාමට පෙර බොහෝ විට අනිවාර්ය වන්නේ කුමක්ද?", "සමථ මණ්ඩලයට යොමු කර නොවිසඳුණු සහතිකයක් ලබාගැනීම", "පාර්ලිමේන්තුවෙන් අවසර ගැනීම", "ජනමත විචාරණයක් තැබීම", "පුවත්පත් දැන්වීමක් පළ කිරීම", "නඩු පැවරීමේ කාලය හා වියදම අඩු කර සුහද විසඳුමක් දීමට පළමුව සමථ මණ්ඩලයට යොමු කිරීම අනිවාර්ය කර ඇත."),
    q("සමථ මණ්ඩලයක සමථකරුවන් (Mediators) ක්‍රියා කළ යුතු මූලික ප්‍රමිතීන් මොනවාද?", "අපක්ෂපාතී බව, රහස්‍යභාවය සහ පාර්ශ්ව දෙකටම සමානව සවන් දීම", "දෙදෙනාගෙන් එක් අයෙකුට දඩ නියම කිරීම", "සිරදඬුවම් ලබාදීම", "නඩු තීන්දු බලහත්කාරයෙන් පැටවීම", "සමථකරුවන් පක්ෂග්‍රාහී නොවී ආරවුලේ රහස්‍යභාවය ආරක්ෂා කළ යුතුය."),
    q("ආරවුලකට මැදිහත් වන ස්වාධීන තෙවන පාර්ශ්වයක් දෙපාර්ශ්වයේ කරුණු අසා නීත්‍යානුකූලව බැඳෙන අවසන් තීන්දුවක් දීමේ ක්‍රමය කුමක්ද?", "බේරුම්කරණය (Arbitration)", "සාකච්ඡාව (Negotiation)", "මඟහැරීම (Avoidance)", "සමථකරණය (Mediation)", "විශේෂයෙන් වාණිජ හා කම්කරු ආරවුල්වලදී බේරුම්කරුගේ තීරණය පාර්ශ්ව දෙකටම නීතියෙන් බැඳේ."),
    q("ගැටුම් නිරාකරණයේදී 'දෙපාර්ශ්වයම දිනන' (Win-Win) විසඳුමක් ලබාගත හැකි වඩාත්ම ප්‍රශස්ත ක්‍රමය කුමක්ද?", "සහයෝගීතා සංවාදය හා සමථකරණය", "බලහත්කාරී යටපත් කිරීම", "ප්‍රතිවාදියා සම්පූර්ණයෙන් පරාජය කිරීම", "සන්නිවේදනය සදහටම නතර කිරීම", "පුද්ගලයන්ගේ සැබෑ අවශ්‍යතා තේරුම් ගෙන දෙදෙනාටම ප්‍රතිලාභ ලැබෙන එකඟතාවකට ඒම Win-Win ක්‍රමයයි."),
    q("ගැටුම් විසඳීමේදී එක් පාර්ශ්වයක් පමණක් තම බලය යොදා ජයගෙන අනෙක් පාර්ශ්වය සම්පූර්ණයෙන් පරාජය කිරීම කුමන ප්‍රතිඵලයක්ද?", "දිනුම්-පැරදුම් (Win-Lose) ප්‍රතිඵලය", "දිනුම්-දිනුම් (Win-Win) ප්‍රතිඵලය", "සම සම්මුතිය", "සාමූහික එකඟතාව", "Win-Lose ක්‍රමයේදී පරාජිත පාර්ශ්වය තුළ අසතුට ඉතිරි වී අනාගතයේදී යළි ගැටුම් මතු විය හැක."),
    q("ගැටුමක් විසඳීමේදී තමන්ගේම අදහස පමණක් සත්‍ය යැයි සිතා කටයුතු නොකර අනෙකාගේ තත්ත්වය තේරුම් ගැනීමේ කුසලතාව කුමක්ද?", "සක්‍රීය සවන්දීම හා සහකම්පනය (Active Listening & Empathy)", "ප්‍රතික්ෂේප කිරීම", "අවලාද නැගීම", "දෘඩ ස්ථාවරය", "ගැටුම් නිරාකරණයේ පළමු පියවර වන්නේ අනෙක් පාර්ශ්වයේ හැඟීම් හා ගැටලුවලට අවධානයෙන් සවන් දීමයි."),
    q("අධිකරණයට ගොස් නඩු පැවරීමට (Litigation) වඩා සමථකරණය හා බේරුම්කරණය වැනි විකල්ප ආරවුල් විසඳීමේ ක්‍රම (ADR) වාසිදායක වන්නේ ඇයි?", "කාලය හා මුදල් ඉතිරි වීමත්, දෙපාර්ශ්වයේ සබඳතාව බිඳ නොවැටීමත් නිසාය", "විනිසුරුවරුන් කිසිදා නොසිටීම නිසාය", "දඬුවම් දස ගුණයකින් වැඩි නිසාය", "නීතිය සම්පූර්ණයෙන් අහෝසි වන නිසාය", "ADR ක්‍රම මඟින් අධිකරණ තදබදය අඩු වී සමාජ සුහදතාව රැකෙන ඉක්මන් විසඳුම් ලැබේ."),
    q("නූතන යහපාලනය තුළ 'සමාජ විගණනය' (Social Audit) යනුවෙන් හඳුන්වන්නේ කුමක්ද?", "ප්‍රදේශයේ පුරවැසියන් හා සිවිල් කණ්ඩායම් රාජ්‍ය ව්‍යාපෘතිවල ප්‍රගතිය හා ගුණාත්මක බව සෘජුවම පරීක්ෂා කිරීම", "පෞද්ගලික බැංකු ගිණුම් පරීක්ෂා කිරීම", "පාසල් සිසුන්ගේ පොත් පරීක්ෂා කිරීම", "රේගු බදු ලිපිගොනු වසා දැමීම", "ගමේ පාරක් හෝ ගොඩනැගිල්ලක් නිසි ප්‍රමිතියෙන් ඉදිවේද යන්න ජනතාව පරීක්ෂා කිරීම වගවීම වැඩි කරයි."),
    q("රටක රාජ්‍ය පරිපාලනය දූෂණයෙන් තොර කිරීමට 'අභ්‍යන්තර විගණනය' සහ 'ස්වාධීන විගණනය' අතර ඇති වෙනස කුමක්ද?", "ස්වාධීන විගණනය ආයතනයෙන් පිටත ස්වාධීන විගණකාධිපති කාර්යාලය මඟින් සිදු කිරීම", "අභ්‍යන්තර විගණනය විදේශ රටවලින් කිරීම", "ස්වාධීන විගණනය අමාත්‍යාංශ ලේකම් තනිව කිරීම", "දෙකම මැතිවරණ කොමිසම මඟින් කිරීම", "ආයතනයෙන් බාහිර ස්වාධීන විගණකාධිපති පරීක්ෂාව මඟින් මූල්‍ය අක්‍රමිකතා සැඟවීම වැළැක්වේ."),
    q("පාසල් පන්ති කාමරයක් තුළ සිසුන් දෙදෙනෙකු අතර ඇතිවන මතභේදයක් ප්‍රචණ්ඩ නොවී විසඳීමට පන්ති නායකයෙකු ගත යුතු නිවැරදි පියවර කුමක්ද?", "දෙදෙනාටම කරුණු ඉදිරිපත් කිරීමට ඉඩ දී සාධාරණ සම්මුතියකට මග පෙන්වීම", "එක් අයෙකුට පමණක් පහර දීම", "දෙදෙනාම පාසලෙන් නෙරපීම", "කටකතා පැතිරවීම", "කුඩා අවධියේ සිටම සාකච්ඡාවෙන් ගැටලු විසඳීම ප්‍රජාතන්ත්‍රවාදී සාම සංස්කෘතියක් ගොඩනඟයි."),
    q("රජයේ භාණ්ඩ හා සේවා මිලදී ගැනීමේදී 'විවෘත තරගකාරී ටෙන්ඩර් ක්‍රමය' භාවිත කිරීමෙන් තහවුරු වන යහපාලන ලක්ෂණය කුමක්ද?", "විනිවිදභාවය, සාධාරණත්වය හා මහජන මුදල් ඉතිරි වීම", "එක් හිතවතෙකුට පමණක් කොන්ත්‍රාත් ලැබීම", "ව්‍යාපෘති කාලය නතර වීම", "රාජ්‍ය බදු අහෝසි වීම", "ප්‍රසිද්ධ දැන්වීම් මඟින් සුදුසුම හා අඩුම මිල ඇති සැපයුම්කරු තේරීම දූෂණ වළක්වයි."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ අවශ්‍ය ආධාරක ගාස්තු ගෙවීමට නොහැකි අඩු ආදායම්ලාභී පුරවැසියන්ට හිමිවන සහනය කුමක්ද?", "පිටපත් ගාස්තු ආදියෙන් නිදහස් වී නොමිලේ තොරතුරු ලබාගැනීමේ අවස්ථාව", "වසර පහක් ප්‍රමාද කර තොරතුරු දීම", "නීතිඥවරයෙකු අනිවාර්ය කිරීම", "කිසිදු තොරතුරක් නොදීම", "ආර්ථික දුෂ්කරතා නිසා කිසිදු පුරවැසියෙකුගේ තොරතුරු අයිතිය අහිමි නොවීමට RTI රෙගුලාසි සහන සලසයි."),
    q("විධායක නිලධාරියෙකු තම තීරණයක් ගැනීමේදී 'තීරණයට හේතු ලිඛිතව දැක්වීම' (Giving Reasons) නීතියේ ආධිපත්‍යයට වැදගත් වන්නේ ඇයි?", "අත්තනෝමතික හා පක්ෂග්‍රාහී තීරණ ගැනීම වැළැක්වීමට", "කඩදාසි භාවිතය වැඩි කිරීමට", "අධිකරණ නඩු ප්‍රමාද කිරීමට", "ව්‍යවස්ථාව වෙනස් කිරීමට", "තීරණයකට හේතු පැහැදිලි කිරීමෙන් පරිපාලන තීරණවල සාධාරණ බව අධිකරණයට හා ජනතාවට පරීක්ෂා කළ හැක."),
    q("රාජ්‍ය පාලනය තුළ 'සංවරණ හා තුලන ක්‍රමය' (Checks and Balances) හා යහපාලනය අතර ඇති සම්බන්ධතාව කුමක්ද?", "එක් ආයතනයක් බලය අයුතු ලෙස භාවිත කරන විට අනෙක් ආයතන එය පාලනය කර වගවීම රැකීම", "සියලු බලතල එක් අයෙකුට පැවරීම", "පාර්ලිමේන්තුව හා අධිකරණය වසා දැමීම", "බදු ආදායම් අහෝසි කිරීම", "බලතල අධික ලෙස ඒකරාශී වීම වැළැක්වීම යහපාලනයේ හා නීතියේ ආධිපත්‍යයේ පදනමයි."),
    q("ශ්‍රී ලංකාවේ දූෂණ විරෝධී පනත යටතේ දේශපාලන නියෝජිතයෙකු 'මහජන සේවකයෙකු' ලෙස සැලකීමෙන් සිදුවන්නේ කුමක්ද?", "ඔවුන්ද අල්ලස්, දූෂණ හා වත්කම් ප්‍රකාශ නීතිවලට යටත් වීම", "ඔවුන්ට නඩු පැවරීම තහනම් වීම", "රජයේ මුදල් පෞද්ගලිකව භාවිත කිරීමට ඉඩ ලැබීම", "මැතිවරණ පැවැත්වීම අවශ්‍ය නොවීම", "මන්ත්‍රීවරුන්, පළාත් සභා හා පළාත් පාලන නියෝජිතයන් සියල්ල නීතිය හමුවේ වගකිව යුතුය."),
    q("ගැටුමක මූල හේතු (Root Causes) හඳුනා නොගෙන තාවකාලිකව එය යටපත් කිරීමෙන් ඇතිවන අවදානම කුමක්ද?", "අනාගතයේදී එම ගැටුම වඩාත් දරුණු ලෙස යළි මතු වීම", "සාමය සදහටම තහවුරු වීම", "සමාජ සංවර්ධනය වේගවත් වීම", "ආර්ථික සමෘද්ධිය ඇති වීම", "අසාධාරණය හෝ මූලික හේතුව විසඳන තුරු තිරසාර සාමයක් ගොඩනැගිය නොහැක."),
    q("ශ්‍රී ලංකාවේ පාර්ලිමේන්තු මැතිවරණයකින් පසු පත්වන රජයක් වුවද 'නීතියේ ආධිපත්‍යය' අනුව ක්‍රියා කළ යුත්තේ කෙසේද?", "ව්‍යවස්ථාවට හා අධිකරණ තීන්දුවලට ගරු කරමින් පවතින නීති රාමුව තුළ පමණි", "තමන්ට ඡන්දය දුන් අයට පමණක් නීතිය ක්‍රියාත්මක කරමින්", "ප්‍රතිවාදීන්ට එරෙහිව නීතිය නොසලකා හැරීමෙන්", "මූලික අයිතිවාසිකම් අවලංගු කරමින්", "බහුතර ඡන්ද බලය ලැබුණද පාලකයන් ආණ්ඩුක්‍රම ව්‍යවස්ථාවේ සීමාවන්ට යටත්ය."),
    q("ග්‍රාමීය හා නාගරික ප්‍රජාව තුළ 'සංස්කෘතික හා ආගමික ගැටුම්' වළක්වා ගැනීමට ඇති හොඳම ප්‍රවේශය කුමක්ද?", "අන්තර් ආගමික සංවාද, මිත්‍රත්වය හා වැරදි මත දුරු කිරීම", "වෙනත් ප්‍රජාවන් සමඟ කතා කිරීම නතර කිරීම", "ආගමික උත්සව තහනම් කිරීම", "සමාජ මාධ්‍යවල උපහාසාත්මක පුවත් පළ කිරීම", "එකිනෙකාගේ සංස්කෘතීන් හඳුනාගෙන අන්‍යෝන්‍ය විශ්වාසය ගොඩනැගීම සාමය තහවුරු කරයි."),
    q("තොරතුරු දැනගැනීමේ පනත යටතේ පුරවැසියන්ට රජයේ ආයතනයකින් නිවැරදි තොරතුරු ලබාගැනීමේදී තොරතුරු නිලධාරියා සිතාමතා වැරදි තොරතුරු දුනහොත් කුමක් වේද?", "RTI පනතේ 39 වගන්තිය යටතේ දඩ හා සිරදඬුවම් ලැබිය හැකි වරදකි", "නිලධාරියාට උසස්වීමක් හිමිවේ", "පුරවැසියාට දඩ ගැසේ", "කොමිෂන් සභාව අවලංගු වේ", "සිතාමතා තොරතුරු සැඟවීම, විනාශ කිරීම හෝ බොරු තොරතුරු දීම නීතියෙන් දඬුවම් ලැබිය හැකි වරදකි."),
    q("යහපාලන මූලධර්ම අනුව රාජ්‍ය නිලධාරීන් තම රාජකාරි කාලය තුළ පුරවැසියන්ට සැලකිය යුතු ආකාරය කුමක්ද?", "කාරුණිකව, අපක්ෂපාතීව හා ප්‍රමාදයකින් තොරව සේවය සැලසීම", "තනතුරේ බලය පෙන්වා පුරවැසියන් රස්තියාදු කිරීම", "ධනවත් අයට පමණක් ප්‍රමුඛතාව දීම", "දේශපාලන ලිපි ඇති අයට පමණක් සේවය කිරීම", "මහජන බදු මුදලින් වැටුප් ලබන රාජ්‍ය සේවකයන් සැමට සමාන ගරුත්වයෙන් සේවය කළ යුතුය."),
    q("ජාත්‍යන්තර වශයෙන් රටවල් අතර යහපාලනය හා දූෂණ විරෝධය මැනීම සඳහා 'ට්‍රාන්ස්පේරන්සි ඉන්ටර්නැෂනල්' ආයතනය නිකුත් කරන දර්ශකය කුමක්ද?", "දූෂණ සංජානන දර්ශකය (Corruption Perceptions Index)", "මානව සංවර්ධන දර්ශකය", "සතුටුදායක රටවල් දර්ශකය", "වායු ගුණාත්මක දර්ශකය", "රාජ්‍ය අංශයේ විනිවිදභාවය හා දූෂණ මට්ටම ජාත්‍යන්තරව අධීක්ෂණය කිරීමට CPI දර්ශකය යොදා ගනී."),
    q("ගැටුම් නිරාකරණයේදී 'සම්මුතියකට එළඹීම' (Compromise) යන්නෙන් අදහස් කරන්නේ කුමක්ද?", "දෙපාර්ශ්වයම සිය ඉල්ලීම්වලින් කොටසක් අත්හැර පොදු එකඟතාවකට පැමිණීම", "එක් පාර්ශ්වයක් සම්පූර්ණයෙන් යටත් වීම", "ආරවුල අමතක කර දැමීම", "අධිකරණ තීන්දුව ප්‍රතික්ෂේප කිරීම", "එකඟතාවකට පැමිණීම සඳහා දෙපාර්ශ්වයම නම්‍යශීලීව සමහර කොන්දේසි ලිහිල් කිරීම සම්මුතියයි."),
    q("ශ්‍රී ලංකාවේ ඕනෑම පුරවැසියෙකුට අධිකරණයෙන් පිටතදී තම වාණිජ ගිවිසුම් ආරවුලක් විසඳාගැනීම සඳහා යොමු විය හැකි නීතිමය පනත කුමක්ද?", "1995 අංක 11 දරන බේරුම්කරණ පනත (Arbitration Act)", "1987 පළාත් සභා පනත", "2003 පාරිභෝගික පනත", "1996 මානව හිමිකම් පනත", "දේශීය හා ජාත්‍යන්තර වාණිජ ආරවුල් කඩිනමින් විසඳීමට 1995 බේරුම්කරණ පනත භාවිත කෙරේ."),
    q("විද්‍යුත් පාලනය (e-Governance) හඳුන්වා දීමෙන් රාජ්‍ය සේවයේ 'විනිවිදභාවය' ඉහළ යන්නේ කෙසේද?", "අයදුම්පත් තත්ත්වය, බලපත්‍ර හා ගෙවීම් ඩිජිටල් ලෙස සටහන් වී අතරමැදි බලපෑම් අඩු වීමෙන්", "ලිපිගොනු සඟවා තැබීමෙන්", "සියලුම කාර්යාල වසා දැමීමෙන්", "මහජන පැමිණිලි මකා දැමීමෙන්", "ඩිජිටල් සටහන් තැබීම නිසා ලිපිගොනු ප්‍රමාද කිරීම හෝ අල්ලස් ඉල්ලීම වැනි අක්‍රමිකතා පාලනය වේ."),
    q("සාමූහික තීරණ ගැනීමේදී යහපාලන මූලධර්මයක් වන 'සහභාගීත්වය' (Participation) යන්නට අනුව රජයක් කළ යුත්තේ කුමක්ද?", "ප්‍රතිපත්ති සෑදීමේදී ස්ත්‍රී පුරුෂ, තරුණ හා සුළුතර ඇතුළු සියලු පුරවැසියන්ට අදහස් දැක්වීමට ඉඩ දීම", "උපදේශකයන් දෙදෙනෙකුගෙන් පමණක් විමසීම", "පනත් කෙටුම්පත් රහසිගතව සම්මත කිරීම", "මැතිවරණ පැවැත්වීම ප්‍රමාද කිරීම", "තීරණයකින් බලපෑමට ලක්වන සෑම ප්‍රජා කොටසකටම ඍජුව හෝ නියෝජිතයන් මඟින් හඬක් නැගීමට ඉඩ තිබිය යුතුය."),
    q("පවුලේ හෝ පාසලේ ගැටුමක් විසඳීමේදී 'පුද්ගලයාට නොව ගැටලුවට පහර දීම' යන මූලධර්මයෙන් අදහස් කරන්නේ කුමක්ද?", "පුද්ගලයන්ට අපහාස නොකර ගැටලුව විසඳන ආකාරය කෙරෙහි පමණක් අවධානය යොමු කිරීම", "ප්‍රතිවාදියාට ශාරීරිකව පහර දීම", "සියලු වැරදි අන් අය මත පැටවීම", "ප්‍රශ්නය සම්පූර්ණයෙන් මඟහැරීම", "පුද්ගල ගෞරවය ආරක්ෂා කරමින් ගැටලුවේ හේතුව විසඳීමෙන් දිගුකාලීන මිත්‍රත්වය රැකේ."),
    q("නීතියේ ආධිපත්‍යය රැකීම සඳහා 'පොලිස් සේවය' තුළ පැවතිය යුතු ප්‍රධානතම ගුණාංගය කුමක්ද?", "දේශපාලන බලපෑම්වලින් තොරව සැමට සමානව නීතිය ක්‍රියාත්මක කිරීම", "පාලක පක්ෂයේ සාමාජිකයන්ට පමණක් ආරක්ෂාව දීම", "අධිකරණ නියෝග නොසලකා හැරීම", "මානව හිමිකම් කොමිසම ප්‍රතික්ෂේප කිරීම", "නීතිය ක්‍රියාත්මක කරන ආයතන අපක්ෂපාතී නොවුණහොත් පුරවැසියන්ගේ නීතිගරුක විශ්වාසය බිඳ වැටේ."),
    q("ශ්‍රී ලංකාවේ පුරවැසියෙකු තම ප්‍රදේශයේ පාරක් ඉදිකිරීමේ වියදම් ගැන තොරතුරු දැනගැනීමට RTI ඉල්ලීමක් යොමු කළ විට එම අයිතිය අයත් වන්නේ කුමන ව්‍යවස්ථා වගන්තියටද?", "14අ (14A) වගන්තිය", "9 වන වගන්තිය", "28 වන වගන්තිය", "156 වන වගන්තිය", "2015 දී 19 වන සංශෝධනයෙන් තොරතුරු දැනගැනීමේ අයිතිය 14අ මූලික අයිතිවාසිකම ලෙස ඇතුළත් කෙරිණි."),
    q("යහපාලනය තුළ 'සාධාරණත්වය හා අන්තර්කරණය' (Equity & Inclusiveness) මඟින් විශේෂ අවධානය යොමු කරන්නේ කවුරුන් කෙරෙහිද?", "සමාජයේ ආන්තික වූ, ආබාධිත, දිළිඳු හා අවදානම් කණ්ඩායම් සංවර්ධනයට එක්කර ගැනීම", "ධනවත් ව්‍යාපාරිකයන්ට පමණක් බදු නිදහස දීම", "නාගරික ප්‍රදේශ පමණක් සංවර්ධනය කිරීම", "විදේශීය සංචාරකයන්ට පමණක් පහසුකම් සැලසීම", "සෑම පුරවැසියෙකුටම තම යහපැවැත්ම වැඩි දියුණු කර ගැනීමට සමාන අවස්ථා හිමිවිය යුතුය."),
    q("නීති විශාරදයන්ට අනුව 'ප්‍රමාද වූ යුක්තිය යනු ප්‍රතික්ෂේප කළ යුක්තියයි' (Justice delayed is justice denied) යන්නෙන් පෙන්වන්නේ කුමක්ද?", "නඩු විභාග වසර ගණනාවක් ප්‍රමාද වීමෙන් වින්දිතයාට සැබෑ සාධාරණය නොලැබී යාම", "නඩු විභාග රහසිගතව පැවැත්වීමේ වාසිය", "සියලු අධිකරණ වසා දැමීමේ අවශ්‍යතාව", "විනිසුරුවරුන් විදේශයෙන් ගෙන්වීම", "කඩිනම් හා සාධාරණ නඩු විභාග නීතියේ ආධිපත්‍යය සුරැකීම සඳහා අත්‍යවශ්‍ය වේ."),
    q("ගැටුමක් නිරාකරණය කිරීමේදී 'තැරැව්කාර මැදිහත්වීම හා සමථකරණය' සාර්ථක වීමට නම් තෙවන පාර්ශ්වය තුළ තිබිය යුතු ප්‍රධාන ලක්ෂණය කුමක්ද?", "දෙපාර්ශ්වයේම විශ්වාසය දිනාගත් මධ්‍යස්ථභාවය", "ආයුධ බලය හා ධනය", "ප්‍රතිවාදී පාර්ශ්වයට බැණ වැදීම", "පුවත්පත්වල රහස් පළ කිරීම", "මධ්‍යස්ථභාවය ගිලිහුණු සමථකරුවෙකු කෙරෙහි ආරවුල්කරුවන් විශ්වාසය නොතබයි."),
    q("ශ්‍රී ලංකාවේ අල්ලස් හෝ දූෂණ විරෝධී පනත (2023) යටතේ 'රාජ්‍ය නොවන හා පෞද්ගලික අංශයේ අල්ලස්' පවා විමර්ශනයට ඇතුළත් කිරීම වැදගත් වන්නේ ඇයි?", "පොදු සැපයුම් හා ව්‍යාපාරික ගනුදෙනුවල දූෂණය සම්පූර්ණයෙන් පිටුදැකීමට", "පෞද්ගලික ව්‍යාපාර තහනම් කිරීමට", "බැංකු පද්ධතිය අහෝසි කිරීමට", "මැතිවරණ කල් දැමීමට", "රාජ්‍ය අංශයට පමණක් නොව පෞද්ගලික අංශය සමඟ බැඳුණු දූෂණද 2023 පනත යටතේ වරදක් කර ඇත."),
    q("යහපාලනයේදී රාජ්‍ය ප්‍රතිපත්ති ක්‍රියාත්මක කිරීම 'නීතිමය රාමුවකට අනුකූලව' සිදු කිරීමෙන් පුරවැසියාට ලැබෙන සහතිකය කුමක්ද?", "පාලකයන් මාරු වුවද පුරවැසි අයිතීන් හා ක්‍රියාපටිපාටි අත්තනෝමතිකව වෙනස් නොවීම", "විපක්ෂ පක්ෂ සියල්ල තහනම් වීම", "අධිකරණ තීන්දු ක්‍රියාත්මක නොවීම", "බදු අය කිරීම අහෝසි වීම", "පුද්ගලයන්ගේ කැමැත්තට වඩා ස්ථාවර නීති රාමුව මත පාලනය රැඳීම සුරක්ෂිතභාවය ගෙන දේ."),
    q("ශ්‍රී ලංකාවේ පාසල් පද්ධතිය තුළ 'සිසු සමථ මණ්ඩල' වැඩසටහන් ක්‍රියාත්මක කිරීමේ ප්‍රධාන අරමුණ කුමක්ද?", "පාසල් වියේ සිටම සිසුන් අතර ඇතිවන ආරවුල් සංවාදයෙන් හා සුහදව විසඳීමට පුරුදු කිරීම", "ගුරුවරුන්ට වැටුප් ගෙවීම", "විභාග ප්‍රතිඵල වෙනස් කිරීම", "පාසල් ගොඩනැගිලි බදු දීම", "සාමකාමී ගැටුම් නිරාකරණ කුසලතා තරුණ පරපුර තුළ වගා කිරීම ඉන් අපේක්ෂා කෙරේ."),
    q("රටේ ඉහළම පරිපාලන නිලධාරියෙකු හෝ ඇමතිවරයෙකු අධිකරණයට අපහාස කිරීමේ වරදකට හෝ මාර්ග නීති කඩ කිරීමකට දඬුවම් ලැබීම පෙන්නුම් කරන්නේ කුමක්ද?", "නීතිය ඉදිරියේ සියලු පුරවැසියන් සමාන වීමේ නීතියේ ආධිපත්‍යය", "විධායකයට ඇති පරම මුක්තිය", "සමානුපාතික මැතිවරණ ක්‍රමය", "පළාත් සභා බලතල", "තනතුර හෝ ධනය නොතකා වැරදිකරුට සමානව නීතිය ක්‍රියාත්මක වීම නීතියේ ආධිපත්‍යයේ ජයග්‍රහණයකි."),
    q("රාජ්‍ය ආයතනයක තීරණ ගැනීමේ ක්‍රියාවලියේදී 'මහජන උපදේශන' (Public Consultations) පැවැත්වීමෙන් සිදුවන්නේ කුමක්ද?", "ප්‍රතිපත්ති පිළිබඳ විශේෂඥ හා ජනතා අදහස් ලැබී වඩාත් හොඳ තීරණ ගැනීමට හැකි වීම", "ව්‍යාපෘති සම්පූර්ණයෙන් නතර වීම", "විදේශ ණය අහෝසි වීම", "අධිකරණ නඩු අවලංගු වීම", "ජනතාවගේ සැබෑ අවශ්‍යතා හා ගැටලු කල්තියා හඳුනාගැනීමට මහජන උපදේශන ඉවහල් වේ."),
    q("ගැටුම් නිරාකරණයේදී 'කරුණු හා හැඟීම් වෙන්කර හඳුනාගැනීම' වැදගත් වන්නේ ඇයි?", "කෝපයෙන් හා පක්ෂග්‍රාහී හැඟීම්වලින් තොරව සැබෑ ගැටලුවට තාර්කික විසඳුමක් සෙවීමට", "අනෙක් පාර්ශ්වයට අපහාස කිරීමට", "සංවාදය වහාම නතර කිරීමට", "නීතිඥ ගාස්තු වැඩි කිරීමට", "හැඟීම්බරව තීරණ ගැනීම වෙනුවට සාක්ෂි හා කරුණු මත සාකච්ඡා කිරීම සාර්ථක විසඳුමකට මග පාදයි.")
  )
}
